package com.ricozknow.enterprise.webhook; import com.ricozknow.common.TenantContext; import com.ricozknow.webhook.*; import lombok.RequiredArgsConstructor; import org.springframework.data.redis.core.StringRedisTemplate; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.*;
@Service @RequiredArgsConstructor public class WebhookDlqService {private final WebhookDeadLetterRepository dlq; private final WebhookDeliveryRepository deliveries; private final StringRedisTemplate redis; private final ObjectMapper objectMapper; @Transactional public WebhookDeadLetter move(WebhookDelivery d){WebhookDeadLetter x=new WebhookDeadLetter();x.setTenantId(d.getTenantId());x.setDeliveryId(d.getId());x.setSubscriptionId(d.getSubscriptionId());x.setEventType(d.getEventType().name());x.setPayload(d.getPayload());x.setReason(d.getLastError());x.setAttemptCount(d.getAttemptCount());return dlq.save(x);} @Transactional(readOnly=true) public List<WebhookDeadLetter> list(){return dlq.findByTenantIdOrderByCreatedAtDesc(TenantContext.get());} @Transactional public WebhookDeadLetter replay(UUID id){WebhookDeadLetter x=dlq.findById(id).filter(d->TenantContext.get().equals(d.getTenantId())).orElseThrow(()->new IllegalArgumentException("DLQ item not found"));WebhookDelivery d=deliveries.findById(x.getDeliveryId()).orElseThrow(()->new IllegalArgumentException("Delivery not found"));d.setStatus(WebhookDelivery.DeliveryStatus.PENDING);d.setLastError("Requeued from DLQ at "+Instant.now());deliveries.save(d);x.setReplayedAt(Instant.now()); try { var job = new java.util.LinkedHashMap<String,Object>(); job.put("tenantId", x.getTenantId()); job.put("eventType", x.getEventType()); job.put("payload", objectMapper.readTree(x.getPayload())); job.put("enqueuedAt", Instant.now().toString()); redis.opsForList().leftPush("ricozknow:webhook-jobs", objectMapper.writeValueAsString(job)); } catch(Exception ex){ throw new IllegalStateException("Failed to enqueue webhook replay", ex); } return dlq.save(x);} }
